function validate([board]) {
  if (!Array.isArray(board) || board.length < 2 || board.length > 100) return 'board needs 2 to 100 rows.';
  const n = board.length;
  for (let i = 0; i < n; i++) {
    const row = board[i];
    if (typeof row !== 'string' || row.length !== n) return 'board must be square: every row is a string of length n.';
    for (let j = 0; j < n; j++) {
      const ch = row[j];
      if (i === 0 && j === 0) {
        if (ch !== 'E') return "The top-left cell must be 'E'.";
      } else if (i === n - 1 && j === n - 1) {
        if (ch !== 'S') return "The bottom-right cell must be 'S'.";
      } else if (ch !== 'X' && (ch < '1' || ch > '9')) {
        return "Other cells must be a digit 1 to 9 or 'X'.";
      }
    }
  }
  return null;
}

