function pathsWithMaxScore(board) {
  const MOD = 1000000007;
  const n = board.length;
  const score = Array.from({ length: n + 1 }, () => new Array(n + 1).fill(-1));
  const ways = Array.from({ length: n + 1 }, () => new Array(n + 1).fill(0));
  score[n - 1][n - 1] = 0;
  ways[n - 1][n - 1] = 1;

  for (let i = n - 1; i >= 0; i--) {
    for (let j = n - 1; j >= 0; j--) {
      const cell = board[i][j];
      if (cell === 'X' || cell === 'S') {
        continue;
      }
      let top = -1;
      let count = 0;
      for (const [r, c] of [[i + 1, j], [i, j + 1], [i + 1, j + 1]]) {
        if (score[r][c] > top) {
          top = score[r][c];
          count = ways[r][c];
        } else if (score[r][c] === top) {
          count = (count + ways[r][c]) % MOD;
        }
      }
      if (top < 0) {
        continue;
      }
      score[i][j] = top + (cell === 'E' ? 0 : Number(cell));
      ways[i][j] = count;
    }
  }
  return score[0][0] < 0 ? [0, 0] : [score[0][0], ways[0][0]];
}

