function pathsWithMaxScore(board) {
  const n = board.length;
  const MOD = 1000000007;
  const memo = new Map();
  // Top-down, walking forward from E: [best score still collectable from (r, c) to S, number of such paths], or null.
  const solve = (r, c) => {
    if (r >= n || c >= n || board[r][c] === 'X') return null;
    if (r === n - 1 && c === n - 1) return [0, 1];
    const key = r * n + c;
    if (memo.has(key)) return memo.get(key);
    const options = [solve(r + 1, c), solve(r, c + 1), solve(r + 1, c + 1)].filter(Boolean);
    let result = null;
    if (options.length > 0) {
      const high = Math.max(...options.map(o => o[0]));
      const total = options.filter(o => o[0] === high).reduce((acc, o) => (acc + o[1]) % MOD, 0);
      const gain = board[r][c] === 'E' ? 0 : board[r][c].charCodeAt(0) - 48;
      result = [high + gain, total];
    }
    memo.set(key, result);
    return result;
  };
  return solve(0, 0) || [0, 0];
}

