function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const n = large ? int(70, 100) : int(2, 5);
  const blocked = (large ? [0, 0.05, 0.15, 0.3] : [0, 0.1, 0.25, 0.45])[int(0, 3)];
  const highest = [1, 2, 9][int(0, 2)];
  const board = [];
  for (let i = 0; i < n; i++) {
    let row = '';
    for (let j = 0; j < n; j++) {
      if (i === 0 && j === 0) row += 'E';
      else if (i === n - 1 && j === n - 1) row += 'S';
      else if (rand() < blocked) row += 'X';
      else row += String(int(1, highest));
    }
    board.push(row);
  }
  return [board];
}
